  "01.model.unit/model.action.ts": "import { Action } from '../99.core/interface/action.interface.js'\nimport ModelBit from './fce/model.bit.js'\n\nexport const INIT_MODEL = '[Model action] Init Model'\nexport class InitModel implements Action {\n    readonly type = INIT_MODEL\n    constructor(public bale: ModelBit) {}\n}\n\nexport const WRITE_MODEL = '[Model action] Write Model'\nexport class WriteModel implements Action {\n    readonly type = WRITE_MODEL\n    constructor(public bale: ModelBit) {}\n}\n\nexport const UPDATE_MODEL = '[Model action] Update Model'\nexport class UpdateModel implements Action {\n    readonly type = UPDATE_MODEL\n    constructor(public bale: ModelBit) {}\n}\n\nexport const CREATE_MODEL = '[Model action] Create Model'\nexport class CreateModel implements Action {\n    readonly type = CREATE_MODEL\n    constructor(public bale: ModelBit) {}\n}\n\nexport const READ_MODEL = '[Model action] Read Model'\nexport class ReadModel implements Action {\n    readonly type = READ_MODEL\n    constructor(public bale: ModelBit) {}\n}\n\nexport const DELETE_MODEL = '[Model action] Delete Model'\nexport class DeleteModel implements Action {\n    readonly type = DELETE_MODEL\n    constructor(public bale: ModelBit) {}\n}\n\nexport const REMOVE_MODEL = '[Model action] Remove Model'\nexport class RemoveModel implements Action {\n    readonly type = REMOVE_MODEL\n    constructor(public bale: ModelBit) {}\n}\n\nexport const LIST_MODEL = '[List action] List Model'\nexport class ListModel implements Action {\n    readonly type = LIST_MODEL\n    constructor(public bale: ModelBit) {}\n}\n\nexport type Actions =\n    | InitModel\n    | UpdateModel\n    | CreateModel\n    | ReadModel\n    | DeleteModel\n    | RemoveModel\n    | WriteModel\n    | ListModel\n",
  "01.model.unit/model.buzzer.ts": "export { initModel } from './buz/model.buzz.js'\nexport { updateModel } from './buz/model.buzz.js'\nexport { readModel } from './buz/model.buzz.js'\nexport { writeModel } from './buz/model.buzz.js'\nexport { removeModel } from './buz/model.buzz.js'\nexport { deleteModel } from './buz/model.buzz.js'\nexport { createModel } from './buz/model.buzz.js'\nexport { listModel } from './buz/model.buzz.js'\n",
  "01.model.unit/model.model.ts": "import Model from './fce/model.interface.js'\nimport ModelBit from './fce/model.bit.js'\n\nexport class ModelModel implements Model {\n    idx: string = ''\n    modelBits: Record<string, ModelBit> = {}\n}\n",
  "01.model.unit/model.reduce.ts": "import clone from 'clone-deep'\nimport * as Act from './model.action.js'\nimport { ModelModel } from './model.model.js'\nimport * as Buzz from './model.buzzer.js'\nimport State from '../99.core/state.js'\n\nexport function reducer(\n    model: ModelModel = new ModelModel(),\n    act: Act.Actions,\n    state?: State,\n) {\n    switch (act.type) {\n        case Act.REMOVE_MODEL:\n            return Buzz.removeModel(clone(model), act.bale, state)\n\n        case Act.DELETE_MODEL:\n            return Buzz.deleteModel(clone(model), act.bale, state)\n\n        case Act.READ_MODEL:\n            return Buzz.readModel(clone(model), act.bale, state)\n\n        case Act.WRITE_MODEL:\n            return Buzz.writeModel(clone(model), act.bale, state)\n\n        case Act.CREATE_MODEL:\n            return Buzz.createModel(clone(model), act.bale, state)\n\n        case Act.UPDATE_MODEL:\n            return Buzz.updateModel(clone(model), act.bale, state)\n\n        case Act.INIT_MODEL:\n            return Buzz.initModel(clone(model), act.bale, state)\n\n        case Act.LIST_MODEL:\n            return Buzz.listModel(clone(model), act.bale, state)\n\n        default:\n            return model\n    }\n}\n",
